dtsPropsFor.River:
/** The river, left to right. Always rendered `width` slots wide even when short. */
  slots: { /** The card in this slot. `null` renders the empty outline. */ category: "clear-path" | "dead-end" | "obstacle" | "trap" | "monster" | "wanderer" | "item" | null; /** Face-down slots hide the category until revealed. */ faceDown?: boolean }[];
  /** How many cards the river holds. @default 3 */
  width?: number;
  /** Position labels under each slot. @default Left / Centre / Right */
  labels?: string[];
  /** Called with the slot index when a card is picked. */
  onPick?: (index: number) => void;
  /** Override scale independently of the provider. */
  size?: "sm" | "md" | "lg";
  className?: string;
  style?: React.CSSProperties;

dtsPropsFor.ActionBar:
/** Which abilities are available this session. Under 5 players, cut to party size. @default all five */
  abilities?: ("forge-a-path" | "scout-ahead" | "its-elementary" | "careful-consideration" | "boost-morale")[];
  /** Abilities disabled by the end-of-round d6 lockout. They stay visible, greyed. */
  locked?: ("forge-a-path" | "scout-ahead" | "its-elementary" | "careful-consideration" | "boost-morale")[];
  /** Difficulty shown on each check line. @default 13 */
  dc?: number;
  /** Called with the ability when an available action is chosen. */
  onUse?: (ability: "forge-a-path" | "scout-ahead" | "its-elementary" | "careful-consideration" | "boost-morale") => void;
  className?: string;
  style?: React.CSSProperties;
